"use client";

import { useEffect, useState } from "react";

interface QueueStatusProps {
  jobId: string;
  onComplete: (reportId: string) => void;
}

interface QueueStatusData {
  status: "pending" | "processing" | "completed" | "failed";
  queue_position?: number;
  estimated_wait_seconds?: number;
  result?: { report_id: string };
  error?: string;
}

export function QueueStatus({ jobId, onComplete }: QueueStatusProps) {
  const [status, setStatus] = useState<QueueStatusData | null>(null);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const pollStatus = async () => {
      try {
        const response = await fetch(`/api/v1/queue/${jobId}/status`);
        const data = await response.json();
        setStatus(data);

        if (data.status === "completed" && data.result) {
          onComplete(data.result.report_id);
        } else if (data.status === "failed") {
          // 에러 처리
        }
      } catch (error) {
        console.error("Failed to fetch queue status:", error);
      }
    };

    const interval = setInterval(pollStatus, 2000);
    pollStatus(); // Initial fetch

    return () => clearInterval(interval);
  }, [jobId, onComplete]);

  if (!status) {
    return <div>Loading...</div>;
  }

  const getStatusMessage = () => {
    switch (status.status) {
      case "pending":
        return `대기열에서 대기 중... (${status.queue_position}번째)`;
      case "processing":
        return "데이터 수집 중... (최대 1분 소요)";
      case "completed":
        return "분석 완료!";
      case "failed":
        return `오류 발생: ${status.error}`;
      default:
        return "처리 중...";
    }
  };

  return (
    <div className="w-full max-w-md mx-auto p-6 bg-white rounded-lg shadow-lg">
      <div className="mb-4">
        <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-purple-500 to-pink-500 transition-all duration-500"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>
      <p className="text-center text-gray-700">{getStatusMessage()}</p>
      {status.estimated_wait_seconds && (
        <p className="text-center text-sm text-gray-500 mt-2">
          예상 대기 시간: {Math.ceil(status.estimated_wait_seconds / 60)}분
        </p>
      )}
    </div>
  );
}
